import redis
s=redis.Redis(host='127.0.0.1', port=6379)
t=redis.Redis(host='127.0.0.1', port=6380)
for db in range(16):
 a=redis.Redis(port=6379,db=db)
 b=redis.Redis(port=6380,db=db)
 sk=set(a.scan_iter(count=1000)); tk=set(b.scan_iter(count=1000))
 assert sk==tk, (db, 'key mismatch', sk-tk, tk-sk)
 for k in sk:
  typ=a.type(k)
  assert typ==b.type(k), (db,k,'type')
  expiry=a.pexpiretime(k); target_expiry=b.pexpiretime(k)
  assert expiry==target_expiry, (db,k,'expiry',expiry,target_expiry)
  if typ==b'string': assert a.get(k)==b.get(k), (db,k,'string')
  elif typ==b'hash': assert a.hgetall(k)==b.hgetall(k), (db,k,'hash')
  elif typ==b'list': assert a.lrange(k,0,-1)==b.lrange(k,0,-1), (db,k,'list')
  elif typ==b'set': assert a.smembers(k)==b.smembers(k), (db,k,'set')
  elif typ==b'zset': assert a.zrange(k,0,-1,withscores=True)==b.zrange(k,0,-1,withscores=True), (db,k,'zset')
  elif typ==b'stream':
   assert a.xrange(k)==b.xrange(k), (db,k,'stream entries')
   assert a.xinfo_stream(k)==b.xinfo_stream(k), (db,k,'stream info')
   ag=a.xinfo_groups(k); bg=b.xinfo_groups(k)
   assert ag==bg,(db,k,'groups',ag,bg)
   for g in ag:
    name=g['name']
    ac=a.xinfo_consumers(k,name); bc=b.xinfo_consumers(k,name)
    assert [(v['name'],v['pending']) for v in ac]==[(v['name'],v['pending']) for v in bc],(db,k,name,'consumers')
    ap=a.xpending_range(k,name,'-','+',100000)
    bp=b.xpending_range(k,name,'-','+',100000)
    assert [(v['message_id'],v['consumer'],v['times_delivered']) for v in ap]==[(v['message_id'],v['consumer'],v['times_delivered']) for v in bp],(db,k,name,'pending')
  else: raise AssertionError((db,k,typ))
 if sk: print('verified db',db, 'keys',len(sk), flush=True)
print('All keys, values, absolute expiries and stream group state verified.')
